/**
 * OPEN A TERMINAL
 *
 * Usage:
 * 1. Drag this macro from the Compendium to your macro hotbar.
 * 2. Open its configuration.
 * 3. Replace TERMINAL_UUID with the Terminal Journal UUID.
 * 4. PAGE_UUID is optional; leave it empty to open the Home page.
 *
 * To copy a UUID in Foundry, right-click the Journal or page and choose
 * “Copy UUID” where available in your interface.
 */

// ── CONFIGURATION TO EDIT ─────────────────────────────────────
const TERMINAL_UUID = "JournalEntry.REPLACE_ME";
const PAGE_UUID = ""; // Example: JournalEntry.xxx.JournalEntryPage.yyy
// ──────────────────────────────────────────────────────────────

const api = game.modules.get("retro-crt-terminal")?.api;
if (!api) return ui.notifications.error("Retro CRT Terminal is not active.");
if (!TERMINAL_UUID || TERMINAL_UUID.includes("REPLACE_ME")) {
  return ui.notifications.warn("Edit TERMINAL_UUID in the macro configuration.");
}

await api.open(TERMINAL_UUID, PAGE_UUID ? { page: PAGE_UUID } : {});
